-- India deep-dive content: page, stats, file_format cards,
-- scope_transmission cards + lifecycle card ("The clearance flow"),
-- steps, penalty rows, penalties_related cards, portal.

INSERT OR IGNORE INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-07-21' FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'en', 'Centralised clearance (IRP)', 'This deep-dive page reflects publicly available technical guidance as of July 2026 and is provided for general awareness, not legal or tax advice. Turnover thresholds, IRP technical requirements, and penalty provisions continue to evolve — confirm current requirements directly on the GST e-Invoice portal or with a GST practitioner before building an integration.', 'India rolled out e-invoicing by progressively lowering the turnover threshold — a gradual widening of scope rather than a single flag-day mandate.', 'India''s e-invoice is a JSON document, not an XML one — a distinction worth flagging since much of the rest of the world defaults to XML.', 'Four institutions share responsibility for how this system runs — worth knowing who does what when something goes wrong.', 'Registration is straightforward if you''re already a GST-registered business — the real work is in building or connecting your IRP submission pipeline.', 'The bigger practical risk isn''t the fine itself — it''s that an invoice without a valid IRN is not a legally valid GST invoice at all.' FROM countries WHERE name_en = 'India';

INSERT OR IGNORE INTO deep_dive_stats (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT ds.id, 'en', 'JSON', 'Schema format (INV-01)' FROM deep_dive_stats ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'India' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stats (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT ds.id, 'en', '₹5 crore', 'AATO threshold' FROM deep_dive_stats ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'India' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stats (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT ds.id, 'en', '30 days', 'IRP reporting window (≥₹10cr)' FROM deep_dive_stats ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'India' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stats (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT ds.id, 'en', '4', 'Governing institutions' FROM deep_dive_stats ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'India' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stats (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT ds.id, 'en', '2020', 'Mandatory since October' FROM deep_dive_stats ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'India' AND ds.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Schema', '[["Format", "Form GST INV-01 (schema v1.1)"], ["Syntax", "JSON"], ["Master codes", "HSN, country, currency, state codes"]]', 'Registered persons continue creating GST invoices in their own accounting/billing/ERP systems as before — the change is that these invoices must now be reported to an IRP before they carry legal force.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'India' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'What "e-invoicing" actually means here', '[["Common misconception", "Government generates the invoice"], ["Reality", "Business generates it; IRP validates and registers it"]]', 'GSTN is explicit on this point in its own FAQ: e-invoicing does not mean invoice generation by a government portal — it means reporting to the IRP and obtaining an IRN.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'India' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'The IRN itself', '[["What it is", "A hash computed by the IRP"], ["Validity rule", "A GST invoice is valid only with a valid IRN"]]', 'The hash the IRP computes over your invoice data becomes the Invoice Reference Number — this is what makes the IRN tamper-evident by construction, not just by policy.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'India' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'QR code contents', '[["Included data", "Seller & buyer GSTINs, invoice number/date, line item count, major-commodity HSN, hash"], ["Printing requirement", "Mandatory on the invoice (Rule 46, CGST Rules)"], ["IRN printing", "Optional — it''s already embedded in the QR code"]]', 'Printing the QR code on separate paper isn''t allowed — it must appear on the invoice itself as one of the mandatory particulars.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'India' AND dc.section = 'file_format' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Governing institutions', '[["GST Council", "Sets policy direction, recommends threshold changes"], ["CBIC", "Translates recommendations into binding notifications"], ["GSTN", "Builds and maintains the IT infrastructure"], ["IRPs", "Multiple authorised portals process and register invoices"]]', 'The Central Board of Indirect Taxes and Customs (CBIC) is the body that actually issues the binding legal notifications — GSTN builds the technology underneath them.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'India' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Submission channels', '[["Direct", "Upload directly to an IRP"], ["Via intermediary", "Through a GST Suvidha Provider (GSP)"], ["No software?", "Free GSTN-empanelled tools, or the offline bulk generation tool"]]', 'Small and medium taxpayers without their own ERP or billing software genuinely aren''t left out — free tooling exists specifically for this case.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'India' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'The 30-day rule''s teeth', '[["Applies to", "AATO ≥ ₹10 crore"], ["Effect", "Invoices older than 30 days are rejected outright by the IRP"]]', 'This isn''t a late-fee situation — past this window, the invoice simply cannot be registered at all, and past invoices cannot be retroactively registered if compliance was missed earlier.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'India' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

