INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'en', 'The clearance flow', 'Every invoice passes through the same sequence:', 'Upon successful registration, the data auto-populates the supplier''s GSTR-1 return — a genuine downstream compliance simplification, not just a formality.' FROM deep_dive_lifecycle_cards dlc JOIN countries co ON co.id = dlc.country_id WHERE co.name_en = 'India';
