INSERT OR IGNORE INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) SELECT dlc.id, 1, 0 FROM deep_dive_lifecycle_cards dlc JOIN countries co ON co.id = dlc.country_id WHERE co.name_en = 'India';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT dls.id, 'en', '2. Upload to IRP' FROM deep_dive_lifecycle_statuses_v2 dls JOIN deep_dive_lifecycle_cards dlc ON dlc.id = dls.card_id JOIN countries co ON co.id = dlc.country_id WHERE co.name_en = 'India' AND dls.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) SELECT dlc.id, 2, 0 FROM deep_dive_lifecycle_cards dlc JOIN countries co ON co.id = dlc.country_id WHERE co.name_en = 'India';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT dls.id, 'en', '3. IRP validates & signs' FROM deep_dive_lifecycle_statuses_v2 dls JOIN deep_dive_lifecycle_cards dlc ON dlc.id = dls.card_id JOIN countries co ON co.id = dlc.country_id WHERE co.name_en = 'India' AND dls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) SELECT dlc.id, 3, 0 FROM deep_dive_lifecycle_cards dlc JOIN countries co ON co.id = dlc.country_id WHERE co.name_en = 'India';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT dls.id, 'en', '4. IRN + QR returned' FROM deep_dive_lifecycle_statuses_v2 dls JOIN deep_dive_lifecycle_cards dlc ON dlc.id = dls.card_id JOIN countries co ON co.id = dlc.country_id WHERE co.name_en = 'India' AND dls.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) SELECT dlc.id, 4, 0 FROM deep_dive_lifecycle_cards dlc JOIN countries co ON co.id = dlc.country_id WHERE co.name_en = 'India';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT dls.id, 'en', '5. Issue to buyer' FROM deep_dive_lifecycle_statuses_v2 dls JOIN deep_dive_lifecycle_cards dlc ON dlc.id = dls.card_id JOIN countries co ON co.id = dlc.country_id WHERE co.name_en = 'India' AND dls.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'en', 'Confirm your aggregate turnover across all GSTINs', 'Check your combined turnover under a single PAN — it only needs to exceed ₹5 crore once in any financial year since 2017–18 to bring you permanently into scope.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'India' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'en', 'Enable e-invoicing on the GST portal if not auto-enabled', 'If your turnover has crossed the threshold but you haven''t been automatically enabled, use Registration → e-Invoice Enablement to switch it on voluntarily.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'India' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'en', 'Choose your submission channel', 'Direct IRP upload, a GST Suvidha Provider, or — if you lack ERP/billing software — a free GSTN-empanelled tool or the offline bulk generation utility.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'India' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'en', 'Enable multi-factor authentication', 'Mandatory on the GST portal for AATO above ₹100 crore since mid-2023, and for AATO ≥ ₹10 crore since April 2025 — confirm your access setup meets the requirement for your bracket.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'India' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'en', 'Build the 30-day reporting window into your workflow', 'If your AATO is ≥ ₹10 crore, automate submission well within 30 days of issuance — there''s no path to registering an invoice after that window closes.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'India' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_steps (country_id, sort_order) SELECT id, 5 FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'en', 'If you''ve missed compliance, act immediately rather than retroactively', 'Past invoices cannot be registered after the fact. Begin compliant generation for all new invoices now, and consult a GST practitioner about voluntary disclosure for the non-compliant period.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'India' AND ds.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT dpr.id, 'en', 'Failure to generate a required e-invoice', 'Penalty under CGST Act non-compliance provisions, tied to tax involved', NULL FROM deep_dive_penalty_rows dpr JOIN countries co ON co.id = dpr.country_id WHERE co.name_en = 'India' AND dpr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT dpr.id, 'en', 'Incorrect or invalid e-invoice', 'Separate penalty for incorrect invoicing under GST law', NULL FROM deep_dive_penalty_rows dpr JOIN countries co ON co.id = dpr.country_id WHERE co.name_en = 'India' AND dpr.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '⚠️ Invalidity is the sharper risk', NULL, NULL, 'An invoice issued without an IRN is not legally a GST invoice — beyond any monetary fine, this can block the buyer''s input tax credit claim entirely, a far more disruptive commercial consequence than the penalty figure itself.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'India' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '🔒 No retroactive fix', NULL, NULL, 'If compliance was missed in a past period, those invoices remain permanently invalid — this makes catching a compliance gap early far more valuable than in regimes that allow retroactive correction.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'India' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '📉 Watch for further threshold reductions', NULL, NULL, 'Given the trajectory from ₹500 crore down to ₹5 crore over five years, further reductions (some discussion has floated ₹2 crore) remain plausible — don''t assume the current threshold is permanent.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'India' AND dc.section = 'penalties_related' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://einvoice1.gst.gov.in', 0 FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'en', 'e-Invoice / IRP (NIC)' FROM deep_dive_portals dp JOIN countries co ON co.id = dp.country_id WHERE co.name_en = 'India' AND dp.sort_order = 0;
